func mergeRustFormationActionListJson(action string, obj1, obj2 map[string]any) {
	list1, ok1 := obj1[action].([]any)
	list2, ok2 := obj2[action].([]any)
	if !ok1 {
		if ok2 {
			obj1[action] = list2
		}
	} else if ok2 {
		obj1[action] = append(list1, list2...)
	}
}

