package trafficpolicy

import (
	"errors"
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"

	envoyroutev3 "github.com/envoyproxy/go-control-plane/envoy/config/route/v3"
	envoy_type_matcher_v3 "github.com/envoyproxy/go-control-plane/envoy/type/matcher/v3"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/durationpb"
	"k8s.io/utils/ptr"

	"github.com/kgateway-dev/kgateway/v2/api/v1alpha1/kgateway"
	"github.com/kgateway-dev/kgateway/v2/pkg/pluginsdk/ir"
	"github.com/kgateway-dev/kgateway/v2/pkg/pluginsdk/policy"
	"github.com/kgateway-dev/kgateway/v2/pkg/utils/regexutils"
)

// consistentHashIR holds the hash policies for each hash source type. Each slice is deduplicated
// by the identifying key of the hash source and preserves the order of first occurrence.
type consistentHashIR struct {
	// disabled suppresses all hash policies on the route
	disabled        bool
	headers         []*envoyroutev3.RouteAction_HashPolicy
	cookies         []*envoyroutev3.RouteAction_HashPolicy
	queryParameters []*envoyroutev3.RouteAction_HashPolicy
	filterState     []*envoyroutev3.RouteAction_HashPolicy
	sourceIP        *envoyroutev3.RouteAction_HashPolicy

	// hashPolicies is the final list of hash policies in canonical type order:
	// headers, cookies, queryParameters, filterState, sourceIp.
	// It is derived from the fields above.
	hashPolicies []*envoyroutev3.RouteAction_HashPolicy
}

var _ PolicySubIR = &consistentHashIR{}

func (c *consistentHashIR) Equals(other PolicySubIR) bool {
	otherCH, ok := other.(*consistentHashIR)
	if !ok {
		return false
	}
	if c == nil || otherCH == nil {
		return c == nil && otherCH == nil
	}
	return c.disabled == otherCH.disabled &&
		hashPoliciesEqual(c.headers, otherCH.headers) &&
		hashPoliciesEqual(c.cookies, otherCH.cookies) &&
		hashPoliciesEqual(c.queryParameters, otherCH.queryParameters) &&
		hashPoliciesEqual(c.filterState, otherCH.filterState) &&
		proto.Equal(c.sourceIP, otherCH.sourceIP) &&
		hashPoliciesEqual(c.hashPolicies, otherCH.hashPolicies)
}

func hashPoliciesEqual(a, b []*envoyroutev3.RouteAction_HashPolicy) bool {
	return slices.EqualFunc(a, b, func(x, y *envoyroutev3.RouteAction_HashPolicy) bool {
		return proto.Equal(x, y)
	})
}

// Validate performs PGV validation on the hash policies and validates header regex rewrites.
func (c *consistentHashIR) Validate() error {
	if c == nil {
		return nil
	}
	for _, hp := range c.hashPolicies {
		if err := hp.Validate(); err != nil {
			return err
		}
		if rr := hp.GetHeader().GetRegexRewrite(); rr != nil {
			if err := regexutils.CheckRegexString(rr.GetPattern().GetRegex()); err != nil {
				return fmt.Errorf("invalid consistentHash header regexRewrite pattern: %w", err)
			}
		}
	}
	return nil
}

// buildHashPolicies computes the final list of hash policies in canonical type order.
// If no hash sources are specified, a single non-terminal source IP hash policy is used.
func (c *consistentHashIR) buildHashPolicies() {
	if c.disabled {
		c.hashPolicies = nil
		return
	}
	out := slices.Concat(c.headers, c.cookies, c.queryParameters, c.filterState)
	if c.sourceIP != nil {
		out = append(out, c.sourceIP)
	}
	if len(out) == 0 {
		out = append(out, sourceIPHashPolicy(false))
	}
	c.hashPolicies = out
}

func sourceIPHashPolicy(terminal bool) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties_{
			ConnectionProperties: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties{
				SourceIp: true,
			},
		},
		Terminal: terminal,
	}
}

// constructConsistentHash constructs the consistent hash policy IR from the policy specification.
func constructConsistentHash(spec kgateway.TrafficPolicySpec, out *trafficPolicySpecIr) error {
	if spec.ConsistentHash == nil {
		return nil
	}
	in := spec.ConsistentHash

	ch := &consistentHashIR{}
	if ptr.Deref(in.Disable, false) {
		ch.disabled = true
		out.consistentHash = ch
		return nil
	}

	var errs []error
	for _, h := range in.Headers {
		hp := &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
				Header: &envoyroutev3.RouteAction_HashPolicy_Header{
					HeaderName: h.HeaderName,
				},
			},
			Terminal: ptr.Deref(h.Terminal, false),
		}
		if h.RegexRewrite != nil {
			hp.GetHeader().RegexRewrite = &envoy_type_matcher_v3.RegexMatchAndSubstitute{
				Pattern: &envoy_type_matcher_v3.RegexMatcher{
					Regex: h.RegexRewrite.Pattern,
				},
				Substitution: h.RegexRewrite.Substitution,
			}
		}
		ch.headers = append(ch.headers, hp)
	}

	for _, c := range in.Cookies {
		cookie := &envoyroutev3.RouteAction_HashPolicy_Cookie{
			Name: c.Name,
			Path: ptr.Deref(c.Path, ""),
		}
		if c.TTL != nil {
			ttl, err := parseCookieTTL(*c.TTL)
			if err != nil {
				errs = append(errs, fmt.Errorf("invalid consistentHash cookie %q ttl: %w", c.Name, err))
				continue
			}
			cookie.Ttl = durationpb.New(ttl)
		}
		for _, attr := range c.Attributes {
			cookie.Attributes = append(cookie.Attributes, &envoyroutev3.RouteAction_HashPolicy_CookieAttribute{
				Name:  attr.Name,
				Value: attr.Value,
			})
		}
		ch.cookies = append(ch.cookies, &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
				Cookie: cookie,
			},
			Terminal: ptr.Deref(c.Terminal, false),
		})
	}

	for _, q := range in.QueryParameters {
		ch.queryParameters = append(ch.queryParameters, &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{
				QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{
					Name: q.Name,
				},
			},
			Terminal: ptr.Deref(q.Terminal, false),
		})
	}

	for _, f := range in.FilterState {
		ch.filterState = append(ch.filterState, &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_FilterState_{
				FilterState: &envoyroutev3.RouteAction_HashPolicy_FilterState{
					Key: f.Key,
				},
			},
			Terminal: ptr.Deref(f.Terminal, false),
		})
	}

	if in.SourceIP != nil {
		ch.sourceIP = sourceIPHashPolicy(ptr.Deref(in.SourceIP.Terminal, false))
	}

	if len(errs) > 0 {
		return errors.Join(errs...)
	}

	ch.headers = dedupHashPolicies(ch.headers)
	ch.cookies = dedupHashPolicies(ch.cookies)
	ch.queryParameters = dedupHashPolicies(ch.queryParameters)
	ch.filterState = dedupHashPolicies(ch.filterState)
	ch.buildHashPolicies()

	out.consistentHash = ch
	return nil
}

// parseCookieTTL parses a cookie TTL given either as a Go duration string (e.g. "1h30m")
// or as an integer number of seconds (e.g. "3600").
func parseCookieTTL(s string) (time.Duration, error) {
	if secs, err := strconv.ParseInt(s, 10, 64); err == nil {
		if secs < 0 {
			return 0, fmt.Errorf("must not be negative: %s", s)
		}
		return time.Duration(secs) * time.Second, nil
	}
	d, err := time.ParseDuration(s)
	if err != nil {
		return 0, err
	}
	if d < 0 {
		return 0, fmt.Errorf("must not be negative: %s", s)
	}
	return d, nil
}

// hashPolicyKey returns the identifying key of a hash policy used for deduplication.
// Header names are case-insensitive, so they are lower-cased.
func hashPolicyKey(hp *envoyroutev3.RouteAction_HashPolicy) string {
	switch spec := hp.GetPolicySpecifier().(type) {
	case *envoyroutev3.RouteAction_HashPolicy_Header_:
		return "header/" + strings.ToLower(spec.Header.GetHeaderName())
	case *envoyroutev3.RouteAction_HashPolicy_Cookie_:
		return "cookie/" + spec.Cookie.GetName()
	case *envoyroutev3.RouteAction_HashPolicy_QueryParameter_:
		return "query/" + spec.QueryParameter.GetName()
	case *envoyroutev3.RouteAction_HashPolicy_FilterState_:
		return "filterState/" + spec.FilterState.GetKey()
	case *envoyroutev3.RouteAction_HashPolicy_ConnectionProperties_:
		return "sourceIp"
	default:
		return ""
	}
}

// dedupHashPolicies returns the hash policies with duplicate keys removed, keeping the first occurrence.
// The input slice is never modified.
func dedupHashPolicies(in []*envoyroutev3.RouteAction_HashPolicy) []*envoyroutev3.RouteAction_HashPolicy {
	if len(in) == 0 {
		return nil
	}
	seen := make(map[string]struct{}, len(in))
	out := make([]*envoyroutev3.RouteAction_HashPolicy, 0, len(in))
	for _, hp := range in {
		key := hashPolicyKey(hp)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, hp)
	}
	return out
}

// mergeConsistentHashIR unions the hash sources of the higher priority (hi) and lower priority (lo)
// policies. Entries of hi come first and duplicates are removed. The sourceIp scalar is always
// taken from hi, even when it is unset.
func mergeConsistentHashIR(hi, lo *consistentHashIR) *consistentHashIR {
	out := &consistentHashIR{
		headers:         dedupHashPolicies(slices.Concat(hi.headers, lo.headers)),
		cookies:         dedupHashPolicies(slices.Concat(hi.cookies, lo.cookies)),
		queryParameters: dedupHashPolicies(slices.Concat(hi.queryParameters, lo.queryParameters)),
		filterState:     dedupHashPolicies(slices.Concat(hi.filterState, lo.filterState)),
		sourceIP:        hi.sourceIP,
	}
	out.buildHashPolicies()
	return out
}

func mergeConsistentHash(
	p1, p2 *TrafficPolicy,
	p2Ref *ir.AttachedPolicyRef,
	p2MergeOrigins ir.MergeOrigins,
	opts policy.MergeOptions,
	mergeOrigins ir.MergeOrigins,
	_ TrafficPolicyMergeOpts,
) {
	const fieldName = "consistentHash"

	p1CH := p1.spec.consistentHash
	p2CH := p2.spec.consistentHash
	if p2CH == nil {
		return
	}
	if p1CH == nil {
		p1.spec.consistentHash = p2CH
		mergeOrigins.SetOne(fieldName, p2Ref, p2MergeOrigins)
		return
	}

	switch opts.Strategy {
	case policy.AugmentedShallowMerge, policy.AugmentedDeepMerge:
		// p1 has higher priority than p2
		if p1CH.disabled || p2CH.disabled {
			// a disabled higher priority policy suppresses p2, and a disabled lower priority
			// policy cannot override the hash policies in p1
			return
		}
		p1.spec.consistentHash = mergeConsistentHashIR(p1CH, p2CH)
		mergeOrigins.Append(fieldName, p2Ref, p2MergeOrigins)

	case policy.OverridableShallowMerge, policy.OverridableDeepMerge:
		// p2 has higher priority than p1
		if p2CH.disabled || p1CH.disabled {
			p1.spec.consistentHash = p2CH
			mergeOrigins.SetOne(fieldName, p2Ref, p2MergeOrigins)
			return
		}
		p1.spec.consistentHash = mergeConsistentHashIR(p2CH, p1CH)
		mergeOrigins.Append(fieldName, p2Ref, p2MergeOrigins)

	default:
		logger.Warn("unsupported merge strategy for policy", "strategy", opts.Strategy, "policy", p2Ref, "field", fieldName)
	}
}

// applyConsistentHash sets the hash policies on the route action.
func applyConsistentHash(ch *consistentHashIR, action *envoyroutev3.RouteAction) {
	if ch == nil || action == nil {
		return
	}
	// When disabled, hashPolicies is nil which clears any hash policies on the route
	action.HashPolicy = ch.hashPolicies
}

