package trafficpolicy

import (
	"fmt"
	"testing"
	"time"

	envoyroutev3 "github.com/envoyproxy/go-control-plane/envoy/config/route/v3"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/durationpb"
	"k8s.io/utils/ptr"

	"github.com/kgateway-dev/kgateway/v2/api/v1alpha1/kgateway"
	"github.com/kgateway-dev/kgateway/v2/pkg/pluginsdk/ir"
	"github.com/kgateway-dev/kgateway/v2/pkg/pluginsdk/policy"
)

// summarizeHashPolicies returns a compact string representation of each hash policy
// in the form "<type>:<key>[:terminal]".
func summarizeHashPolicies(hps []*envoyroutev3.RouteAction_HashPolicy) []string {
	out := make([]string, 0, len(hps))
	for _, hp := range hps {
		var s string
		switch {
		case hp.GetHeader() != nil:
			s = "header:" + hp.GetHeader().GetHeaderName()
		case hp.GetCookie() != nil:
			s = "cookie:" + hp.GetCookie().GetName()
		case hp.GetQueryParameter() != nil:
			s = "query:" + hp.GetQueryParameter().GetName()
		case hp.GetFilterState() != nil:
			s = "filterState:" + hp.GetFilterState().GetKey()
		case hp.GetConnectionProperties().GetSourceIp():
			s = "sourceIp"
		default:
			s = fmt.Sprintf("unknown:%v", hp)
		}
		if hp.GetTerminal() {
			s += ":terminal"
		}
		out = append(out, s)
	}
	return out
}

func mustConstructConsistentHash(t *testing.T, ch *kgateway.ConsistentHash) *consistentHashIR {
	t.Helper()
	out := &trafficPolicySpecIr{}
	require.NoError(t, constructConsistentHash(kgateway.TrafficPolicySpec{ConsistentHash: ch}, out))
	return out.consistentHash
}

func TestConstructConsistentHash(t *testing.T) {
	t.Run("unset", func(t *testing.T) {
		out := &trafficPolicySpecIr{}
		require.NoError(t, constructConsistentHash(kgateway.TrafficPolicySpec{}, out))
		assert.Nil(t, out.consistentHash)
	})

	t.Run("empty defaults to non-terminal sourceIp", func(t *testing.T) {
		got := mustConstructConsistentHash(t, &kgateway.ConsistentHash{})
		assert.Equal(t, []string{"sourceIp"}, summarizeHashPolicies(got.hashPolicies))
		assert.Nil(t, got.sourceIP, "default sourceIp must not be recorded as explicitly set")
	})

	t.Run("disable produces no hash policies", func(t *testing.T) {
		got := mustConstructConsistentHash(t, &kgateway.ConsistentHash{Disable: ptr.To(true)})
		assert.True(t, got.disabled)
		assert.Empty(t, got.hashPolicies)
	})

	t.Run("disable false behaves as enabled", func(t *testing.T) {
		got := mustConstructConsistentHash(t, &kgateway.ConsistentHash{Disable: ptr.To(false)})
		assert.False(t, got.disabled)
		assert.Equal(t, []string{"sourceIp"}, summarizeHashPolicies(got.hashPolicies))
	})

	t.Run("canonical order and dedup", func(t *testing.T) {
		got := mustConstructConsistentHash(t, &kgateway.ConsistentHash{
			SourceIP: &kgateway.ConsistentHashSourceIP{Terminal: ptr.To(true)},
			FilterState: []kgateway.ConsistentHashFilterState{
				{Key: "fs"},
				{Key: "fs", Terminal: ptr.To(true)},
			},
			QueryParameters: []kgateway.ConsistentHashQueryParameter{
				{Name: "q", Terminal: ptr.To(true)},
				{Name: "q"},
				{Name: "Q"},
			},
			Cookies: []kgateway.ConsistentHashCookie{
				{Name: "c1"},
				{Name: "c1", Terminal: ptr.To(true)},
				{Name: "c2"},
			},
			Headers: []kgateway.ConsistentHashHeader{
				{HeaderName: "X-User", Terminal: ptr.To(true)},
				{HeaderName: "x-user"},
				{HeaderName: "x-other"},
			},
		})
		assert.Equal(t, []string{
			"header:X-User:terminal",
			"header:x-other",
			"cookie:c1",
			"cookie:c2",
			"query:q:terminal",
			"query:Q",
			"filterState:fs",
			"sourceIp:terminal",
		}, summarizeHashPolicies(got.hashPolicies))
	})

	t.Run("header regex rewrite", func(t *testing.T) {
		got := mustConstructConsistentHash(t, &kgateway.ConsistentHash{
			Headers: []kgateway.ConsistentHashHeader{{
				HeaderName: "x-tenant",
				RegexRewrite: &kgateway.ConsistentHashRegexRewrite{
					Pattern:      "^tenant-(.*)$",
					Substitution: `\1`,
				},
			}},
		})
		require.Len(t, got.hashPolicies, 1)
		rr := got.hashPolicies[0].GetHeader().GetRegexRewrite()
		require.NotNil(t, rr)
		assert.Equal(t, "^tenant-(.*)$", rr.GetPattern().GetRegex())
		assert.Equal(t, `\1`, rr.GetSubstitution())
		assert.NoError(t, got.Validate())
	})

	t.Run("invalid header regex rewrite fails validation", func(t *testing.T) {
		got := mustConstructConsistentHash(t, &kgateway.ConsistentHash{
			Headers: []kgateway.ConsistentHashHeader{{
				HeaderName:   "x-tenant",
				RegexRewrite: &kgateway.ConsistentHashRegexRewrite{Pattern: "(", Substitution: "x"},
			}},
		})
		assert.Error(t, got.Validate())
	})

	t.Run("cookie fields", func(t *testing.T) {
		got := mustConstructConsistentHash(t, &kgateway.ConsistentHash{
			Cookies: []kgateway.ConsistentHashCookie{{
				Name: "session",
				TTL:  ptr.To("1h30m"),
				Path: ptr.To("/"),
				Attributes: []kgateway.ConsistentHashCookieAttribute{
					{Name: "SameSite", Value: "Lax"},
					{Name: "Secure"},
				},
				Terminal: ptr.To(true),
			}},
		})
		want := &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
				Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{
					Name: "session",
					Ttl:  durationpb.New(90 * time.Minute),
					Path: "/",
					Attributes: []*envoyroutev3.RouteAction_HashPolicy_CookieAttribute{
						{Name: "SameSite", Value: "Lax"},
						{Name: "Secure"},
					},
				},
			},
			Terminal: true,
		}
		require.Len(t, got.hashPolicies, 1)
		assert.True(t, proto.Equal(want, got.hashPolicies[0]), "got %v", got.hashPolicies[0])
		assert.NoError(t, got.Validate())
	})

	t.Run("invalid cookie ttl", func(t *testing.T) {
		out := &trafficPolicySpecIr{}
		err := constructConsistentHash(kgateway.TrafficPolicySpec{ConsistentHash: &kgateway.ConsistentHash{
			Cookies: []kgateway.ConsistentHashCookie{{Name: "c", TTL: ptr.To("abc")}},
		}}, out)
		assert.ErrorContains(t, err, `invalid consistentHash cookie "c" ttl`)
		assert.Nil(t, out.consistentHash)
	})
}

func TestParseCookieTTL(t *testing.T) {
	tests := []struct {
		in      string
		want    time.Duration
		wantErr bool
	}{
		{in: "3600", want: time.Hour},
		{in: "0", want: 0},
		{in: "1h30m", want: 90 * time.Minute},
		{in: "500ms", want: 500 * time.Millisecond},
		{in: "-1", wantErr: true},
		{in: "-1s", wantErr: true},
		{in: "abc", wantErr: true},
		{in: "", wantErr: true},
	}
	for _, tt := range tests {
		t.Run(tt.in, func(t *testing.T) {
			got, err := parseCookieTTL(tt.in)
			if tt.wantErr {
				assert.Error(t, err)
				return
			}
			require.NoError(t, err)
			assert.Equal(t, tt.want, got)
		})
	}
}

func TestConsistentHashIREquals(t *testing.T) {
	a := mustConstructConsistentHash(t, &kgateway.ConsistentHash{
		Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x"}},
	})
	b := mustConstructConsistentHash(t, &kgateway.ConsistentHash{
		Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x"}},
	})
	c := mustConstructConsistentHash(t, &kgateway.ConsistentHash{
		Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x", Terminal: ptr.To(true)}},
	})
	disabled := mustConstructConsistentHash(t, &kgateway.ConsistentHash{Disable: ptr.To(true)})
	empty := mustConstructConsistentHash(t, &kgateway.ConsistentHash{})

	var nilIR *consistentHashIR
	assert.True(t, nilIR.Equals(nilIR))
	assert.False(t, nilIR.Equals(a))
	assert.False(t, a.Equals(nilIR))
	assert.True(t, a.Equals(b))
	assert.False(t, a.Equals(c))
	assert.False(t, disabled.Equals(empty))
}

func TestMergeConsistentHash(t *testing.T) {
	hi := &kgateway.ConsistentHash{
		Headers: []kgateway.ConsistentHashHeader{
			{HeaderName: "x-hi"},
			{HeaderName: "x-shared"},
		},
		Cookies: []kgateway.ConsistentHashCookie{{Name: "c-shared", Terminal: ptr.To(true)}},
	}
	lo := &kgateway.ConsistentHash{
		SourceIP: &kgateway.ConsistentHashSourceIP{Terminal: ptr.To(true)},
		FilterState: []kgateway.ConsistentHashFilterState{
			{Key: "fs-lo"},
		},
		QueryParameters: []kgateway.ConsistentHashQueryParameter{{Name: "q-lo"}},
		Cookies: []kgateway.ConsistentHashCookie{
			{Name: "c-lo"},
			{Name: "c-shared"},
		},
		Headers: []kgateway.ConsistentHashHeader{
			{HeaderName: "X-Shared", Terminal: ptr.To(true)},
			{HeaderName: "x-lo"},
		},
	}
	unionedWithoutSourceIP := []string{
		"header:x-hi",
		"header:x-shared",
		"header:x-lo",
		"cookie:c-shared:terminal",
		"cookie:c-lo",
		"query:q-lo",
		"filterState:fs-lo",
	}

	newPolicy := func(ch *kgateway.ConsistentHash) *TrafficPolicy {
		if ch == nil {
			return &TrafficPolicy{}
		}
		return &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: mustConstructConsistentHash(t, ch)}}
	}
	p2Ref := &ir.AttachedPolicyRef{Group: "gateway.kgateway.dev", Kind: "TrafficPolicy", Namespace: "default", Name: "p2"}

	tests := []struct {
		name          string
		p1, p2        *kgateway.ConsistentHash
		strategy      policy.MergeStrategy
		want          []string
		wantDisabled  bool
		wantNil       bool
		wantP2InOrigs bool
	}{
		{
			name:     "p2 unset keeps p1",
			p1:       hi,
			strategy: policy.AugmentedShallowMerge,
			want:     []string{"header:x-hi", "header:x-shared", "cookie:c-shared:terminal"},
		},
		{
			name:          "p1 unset takes p2",
			p2:            lo,
			strategy:      policy.AugmentedShallowMerge,
			want:          []string{"header:X-Shared:terminal", "header:x-lo", "cookie:c-lo", "cookie:c-shared", "query:q-lo", "filterState:fs-lo", "sourceIp:terminal"},
			wantP2InOrigs: true,
		},
		{
			name:          "augmented shallow unions with p1 first and keeps p1 sourceIp",
			p1:            hi,
			p2:            lo,
			strategy:      policy.AugmentedShallowMerge,
			want:          unionedWithoutSourceIP,
			wantP2InOrigs: true,
		},
		{
			name:          "augmented deep unions with p1 first and keeps p1 sourceIp",
			p1:            hi,
			p2:            lo,
			strategy:      policy.AugmentedDeepMerge,
			want:          unionedWithoutSourceIP,
			wantP2InOrigs: true,
		},
		{
			name:          "overridable unions with p2 first and keeps p2 sourceIp",
			p1:            lo,
			p2:            hi,
			strategy:      policy.OverridableShallowMerge,
			want:          unionedWithoutSourceIP,
			wantP2InOrigs: true,
		},
		{
			name:          "empty higher priority policy does not default when lower priority has entries",
			p1:            &kgateway.ConsistentHash{},
			p2:            &kgateway.ConsistentHash{QueryParameters: []kgateway.ConsistentHashQueryParameter{{Name: "q"}}},
			strategy:      policy.AugmentedShallowMerge,
			want:          []string{"query:q"},
			wantP2InOrigs: true,
		},
		{
			name:          "sourceIp is not inherited from lower priority policy",
			p1:            &kgateway.ConsistentHash{},
			p2:            &kgateway.ConsistentHash{SourceIP: &kgateway.ConsistentHashSourceIP{Terminal: ptr.To(true)}},
			strategy:      policy.AugmentedShallowMerge,
			want:          []string{"sourceIp"},
			wantP2InOrigs: true,
		},
		{
			name:         "disabled higher priority policy suppresses lower priority policy",
			p1:           &kgateway.ConsistentHash{Disable: ptr.To(true)},
			p2:           lo,
			strategy:     policy.AugmentedShallowMerge,
			wantDisabled: true,
		},
		{
			name:     "disabled lower priority policy does not override higher priority policy",
			p1:       hi,
			p2:       &kgateway.ConsistentHash{Disable: ptr.To(true)},
			strategy: policy.AugmentedDeepMerge,
			want:     []string{"header:x-hi", "header:x-shared", "cookie:c-shared:terminal"},
		},
		{
			name:          "overridable disabled p2 suppresses p1",
			p1:            hi,
			p2:            &kgateway.ConsistentHash{Disable: ptr.To(true)},
			strategy:      policy.OverridableDeepMerge,
			wantDisabled:  true,
			wantP2InOrigs: true,
		},
		{
			name:     "both unset",
			strategy: policy.AugmentedShallowMerge,
			wantNil:  true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			p1 := newPolicy(tt.p1)
			p2 := newPolicy(tt.p2)
			var p1Before, p2Before []*envoyroutev3.RouteAction_HashPolicy
			if p1.spec.consistentHash != nil {
				p1Before = cloneHashPolicies(p1.spec.consistentHash.hashPolicies)
			}
			if p2.spec.consistentHash != nil {
				p2Before = cloneHashPolicies(p2.spec.consistentHash.hashPolicies)
			}
			origP1CH := p1.spec.consistentHash
			origP2CH := p2.spec.consistentHash

			mergeOrigins := ir.MergeOrigins{}
			mergeConsistentHash(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: tt.strategy}, mergeOrigins, TrafficPolicyMergeOpts{})

			got := p1.spec.consistentHash
			if tt.wantNil {
				assert.Nil(t, got)
				return
			}
			require.NotNil(t, got)
			assert.Equal(t, tt.wantDisabled, got.disabled)
			if tt.wantDisabled {
				assert.Empty(t, got.hashPolicies)
			} else {
				assert.Equal(t, tt.want, summarizeHashPolicies(got.hashPolicies))
			}
			assert.Equal(t, tt.wantP2InOrigs, mergeOrigins.Get("consistentHash").Has(p2Ref.ID()),
				"merge origins: %v", mergeOrigins)

			// the original IRs must never be modified by a merge
			if origP1CH != nil {
				assert.True(t, hashPoliciesEqual(p1Before, origP1CH.hashPolicies), "p1 IR was mutated")
			}
			if origP2CH != nil {
				assert.True(t, hashPoliciesEqual(p2Before, origP2CH.hashPolicies), "p2 IR was mutated")
			}
		})
	}
}

func TestMergeTrafficPoliciesConsistentHash(t *testing.T) {
	p1 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: mustConstructConsistentHash(t, &kgateway.ConsistentHash{
		Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x-a"}},
	})}}
	p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: mustConstructConsistentHash(t, &kgateway.ConsistentHash{
		Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x-b"}},
	})}}
	p2Ref := &ir.AttachedPolicyRef{Group: "gateway.kgateway.dev", Kind: "TrafficPolicy", Namespace: "default", Name: "p2"}
	mergeOrigins := ir.MergeOrigins{}

	MergeTrafficPolicies(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: policy.AugmentedShallowMerge}, mergeOrigins, TrafficPolicyMergeOpts{})

	assert.Equal(t, []string{"header:x-a", "header:x-b"}, summarizeHashPolicies(p1.spec.consistentHash.hashPolicies))
	assert.True(t, mergeOrigins.Get("consistentHash").Has(p2Ref.ID()))
}

func TestApplyConsistentHash(t *testing.T) {
	existing := []*envoyroutev3.RouteAction_HashPolicy{sourceIPHashPolicy(true)}

	t.Run("nil IR leaves route untouched", func(t *testing.T) {
		action := &envoyroutev3.RouteAction{HashPolicy: existing}
		applyConsistentHash(nil, action)
		assert.Equal(t, existing, action.GetHashPolicy())
	})

	t.Run("sets hash policies", func(t *testing.T) {
		action := &envoyroutev3.RouteAction{}
		applyConsistentHash(mustConstructConsistentHash(t, &kgateway.ConsistentHash{
			FilterState: []kgateway.ConsistentHashFilterState{{Key: "k"}},
			Headers:     []kgateway.ConsistentHashHeader{{HeaderName: "h"}},
		}), action)
		assert.Equal(t, []string{"header:h", "filterState:k"}, summarizeHashPolicies(action.GetHashPolicy()))
	})

	t.Run("disabled clears hash policies", func(t *testing.T) {
		action := &envoyroutev3.RouteAction{HashPolicy: existing}
		applyConsistentHash(mustConstructConsistentHash(t, &kgateway.ConsistentHash{Disable: ptr.To(true)}), action)
		assert.Empty(t, action.GetHashPolicy())
	})
}

func cloneHashPolicies(in []*envoyroutev3.RouteAction_HashPolicy) []*envoyroutev3.RouteAction_HashPolicy {
	out := make([]*envoyroutev3.RouteAction_HashPolicy, 0, len(in))
	for _, hp := range in {
		out = append(out, proto.Clone(hp).(*envoyroutev3.RouteAction_HashPolicy))
	}
	return out
}

