		t.Run(tt.name, func(t *testing.T) {
			p1 := newPolicy(tt.p1)
			p2 := newPolicy(tt.p2)
			var p1Before, p2Before []*envoyroutev3.RouteAction_HashPolicy
			if p1.spec.consistentHash != nil {
				p1Before = cloneHashPolicies(p1.spec.consistentHash.hashPolicies)
			}
			if p2.spec.consistentHash != nil {
				p2Before = cloneHashPolicies(p2.spec.consistentHash.hashPolicies)
			}
			origP1CH := p1.spec.consistentHash
			origP2CH := p2.spec.consistentHash

			mergeOrigins := ir.MergeOrigins{}
			mergeConsistentHash(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: tt.strategy}, mergeOrigins, TrafficPolicyMergeOpts{})

			got := p1.spec.consistentHash
			if tt.wantNil {
				assert.Nil(t, got)
				return
			}
			require.NotNil(t, got)
			assert.Equal(t, tt.wantDisabled, got.disabled)
			if tt.wantDisabled {
				assert.Empty(t, got.hashPolicies)
			} else {
				assert.Equal(t, tt.want, summarizeHashPolicies(got.hashPolicies))
			}
			assert.Equal(t, tt.wantP2InOrigs, mergeOrigins.Get("consistentHash").Has(p2Ref.ID()),
				"merge origins: %v", mergeOrigins)

			// the original IRs must never be modified by a merge
			if origP1CH != nil {
				assert.True(t, hashPoliciesEqual(p1Before, origP1CH.hashPolicies), "p1 IR was mutated")
			}
			if origP2CH != nil {
				assert.True(t, hashPoliciesEqual(p2Before, origP2CH.hashPolicies), "p2 IR was mutated")
			}
		})
	}
}

func TestMergeTrafficPoliciesConsistentHash(t *testing.T) {
	p1 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: mustConstructConsistentHash(t, &kgateway.ConsistentHash{
		Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x-a"}},
	})}}
	p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: mustConstructConsistentHash(t, &kgateway.ConsistentHash{
		Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x-b"}},
	})}}
	p2Ref := &ir.AttachedPolicyRef{Group: "gateway.kgateway.dev", Kind: "TrafficPolicy", Namespace: "default", Name: "p2"}
	mergeOrigins := ir.MergeOrigins{}

	MergeTrafficPolicies(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: policy.AugmentedShallowMerge}, mergeOrigins, TrafficPolicyMergeOpts{})

	assert.Equal(t, []string{"header:x-a", "header:x-b"}, summarizeHashPolicies(p1.spec.consistentHash.hashPolicies))
	assert.True(t, mergeOrigins.Get("consistentHash").Has(p2Ref.ID()))
}

func TestApplyConsistentHash(t *testing.T) {
	existing := []*envoyroutev3.RouteAction_HashPolicy{sourceIPHashPolicy(true)}

	t.Run("nil IR leaves route untouched", func(t *testing.T) {
		action := &envoyroutev3.RouteAction{HashPolicy: existing}
		applyConsistentHash(nil, action)
		assert.Equal(t, existing, action.GetHashPolicy())
	})

	t.Run("sets hash policies", func(t *testing.T) {
		action := &envoyroutev3.RouteAction{}
		applyConsistentHash(mustConstructConsistentHash(t, &kgateway.ConsistentHash{
			FilterState: []kgateway.ConsistentHashFilterState{{Key: "k"}},
			Headers:     []kgateway.ConsistentHashHeader{{HeaderName: "h"}},
		}), action)
		assert.Equal(t, []string{"header:h", "filterState:k"}, summarizeHashPolicies(action.GetHashPolicy()))
	})

	t.Run("disabled clears hash policies", func(t *testing.T) {
		action := &envoyroutev3.RouteAction{HashPolicy: existing}
		applyConsistentHash(mustConstructConsistentHash(t, &kgateway.ConsistentHash{Disable: ptr.To(true)}), action)
		assert.Empty(t, action.GetHashPolicy())
	})
}

func cloneHashPolicies(in []*envoyroutev3.RouteAction_HashPolicy) []*envoyroutev3.RouteAction_HashPolicy {
	out := make([]*envoyroutev3.RouteAction_HashPolicy, 0, len(in))
	for _, hp := range in {
		out = append(out, proto.Clone(hp).(*envoyroutev3.RouteAction_HashPolicy))
	}
	return out
}

